import java.util.*;
import java.io.*;

public class E {
    public static long MOD = 998244353;
    public static long[] fact;
    public static long[] invfact;
    public static void main(String[] args) throws IOException{
        BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
        StringTokenizer st = new StringTokenizer(f.readLine());
        fact = new long[200001];
        invfact = new long[200001];
        fact[0] = 1L;
        invfact[0] = 1L;
        for(int i = 1; i <= 200000; i++){
            fact[i] = (fact[i-1]*i);
            fact[i]%=MOD;
            invfact[i] = pow(fact[i], MOD-2, MOD)%MOD;
        }
        long n = Long.parseLong(st.nextToken());
        long k = Long.parseLong(st.nextToken());
        if(k > n){
            out.println(0);
            out.close();
            System.exit(0);
        }
        k = n-k;
        long ans = 0L;
        for(int i = 0; i <= k; i++){
            long curr = (ncr((int)k, i)*(pow(k-i, n, MOD)))%MOD;
            if(i % 2 == 0) ans+=curr;
            else ans-=curr;
            ans%=MOD;
            ans+=MOD;
            ans%=MOD;
        }
        ans*=(ncr((int)n, (int)k));
        ans%=MOD;
        if(n-k == 0) out.println(ans);
        else out.println((2*ans)%MOD);


        out.close();
    }
    public static long ncr(int n, int r){
        return (((fact[n]*invfact[r])%MOD)*invfact[n-r])%MOD;
    }

    public static long pow(long x, long y, long p){
        long res = 1L;

        while(y > 0){
            if(y % 2 != 0){
                res = (res*x)%p;
            }
            x = (x*x)%p;
            y/=2;
        }
        return res % p;


    }
}

